<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import './styles/ui-tokens.css'
import './styles/shell.css'
import './styles/forms.css'
import './styles/kfe2-shell.css'
import { kfePresentationApi } from './presentation/application/presentation-api.js'
import PerformanceModuleView from './components/PerformanceModuleView.vue'
import AdminModuleView from './components/AdminModuleView.vue'
import DayStartCard from './presentation/DayStartCard.vue'
import ShiftWaitingCard from './presentation/ShiftWaitingCard.vue'
import PersonalTripCard from './presentation/PersonalTripCard.vue'
import BusinessTripCard from './presentation/BusinessTripCard.vue'
import ShiftCard from './presentation/ShiftCard.vue'
import DayEndCard from './presentation/DayEndCard.vue'
import WorkSummaryCard from './presentation/WorkSummaryCard.vue'
import WorkOperationsCard from './presentation/WorkOperationsCard.vue'

const props=defineProps({activeSurface:{type:String,default:'Work'}})
const emit=defineEmits(['surface-select'])
const activeModule=computed(()=>props.activeSurface),online=ref(typeof navigator==='undefined'?true:navigator.onLine),performanceModel=ref(null),currentWorkState=ref(null),latestWorkOdometer=ref(null),personalTripMetrics=ref(null),businessTripMetrics=ref(null),shiftMetrics=ref(null),dayEndSummary=ref(null),completedShiftSummary=ref(null),dailyOperationalReport=ref(null),userError=ref(null)
const clearError=()=>{userError.value=null}
const commandError=(err,fallback='Command failed. Please retry.')=>{console.error(err);userError.value=err?.message||fallback}
function selectTab(tab){const next=String(tab||'').toLowerCase();if(next==='performance')emit('surface-select','Performance');else if(next==='admin')emit('surface-select','Admin')}
let touchStartX=null,touchStartY=null
function isIgnoredTouchTarget(target){if(!(target instanceof Element))return false;if(target.closest('input,button,textarea,select'))return true;const scrollable=target.closest('table,[data-scrollable],.scrollable,.overflow-auto');if(!scrollable)return false;return scrollable.scrollWidth>scrollable.clientWidth||scrollable.scrollHeight>scrollable.clientHeight}
function handleTouchStart(event){const touch=event.changedTouches?.[0];if(!touch||isIgnoredTouchTarget(event.target))return;touchStartX=touch.clientX;touchStartY=touch.clientY}
function handleTouchEnd(event){const touch=event.changedTouches?.[0];if(!touch||touchStartX===null||touchStartY===null){touchStartX=null;touchStartY=null;return}const deltaX=touch.clientX-touchStartX,deltaY=touch.clientY-touchStartY;touchStartX=null;touchStartY=null;if(Math.abs(deltaX)<60||Math.abs(deltaX)<=Math.abs(deltaY)||activeModule.value!=='Work'||isIgnoredTouchTarget(event.target))return;if(deltaX<0)selectTab('performance');else selectTab('admin')}
async function loadPerformance(){try{performanceModel.value=await kfePresentationApi.read.getPerformance()}catch(error){performanceModel.value={error:String(error?.message||error)}}}
async function refreshWorkState(){latestWorkOdometer.value=await kfePresentationApi.read.latestWorkOdometer();const nextState=await kfePresentationApi.read.getWorkScreenState();currentWorkState.value=nextState;if(nextState==='SHIFT'){const shift=await kfePresentationApi.read.getActiveShift();const t=Date.parse(String(shift?.started_at||''));shiftMetrics.value=shift?{shiftId:shift.id,startOdometer:shift.start_odometer,startedAtEpochMs:Number.isFinite(t)?t:null}:null;personalTripMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}else if(nextState==='PERSONAL_TRIP'){const draft=await kfePresentationApi.read.getActiveTripDraft();const t=Date.parse(String(draft?.started_at||''));personalTripMetrics.value=draft?{startOdometer:draft.start_odometer_km,startTimeEpochMs:Number.isFinite(t)?t:null}:null;shiftMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}else if(nextState==='BUSINESS_TRIP'){const draft=await kfePresentationApi.read.getActiveTripDraft();const t=Date.parse(String(draft?.started_at||''));businessTripMetrics.value=draft?{startOdometer:draft.start_odometer_km,startTimeEpochMs:Number.isFinite(t)?t:null}:null;shiftMetrics.value=null;personalTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}else if(nextState==='SHIFT_WAITING'||nextState==='DAY_ENDED'){dayEndSummary.value=await kfePresentationApi.read.getWorkSummary();completedShiftSummary.value=await kfePresentationApi.read.getCompletedShiftSummary();dailyOperationalReport.value=await kfePresentationApi.read.getDailyOperationalReport();shiftMetrics.value=null;personalTripMetrics.value=null;businessTripMetrics.value=null}else{shiftMetrics.value=null;personalTripMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}}
async function loadWorkState(){try{await refreshWorkState()}catch(error){console.error('Failed to load Work state:',error);currentWorkState.value=null;latestWorkOdometer.value=null;shiftMetrics.value=null;personalTripMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}}
async function refreshAll(){await Promise.all([loadPerformance(),refreshWorkState()])}
async function handleStartDay(odometer){try{await kfePresentationApi.commands.startDay({odometer});await refreshAll()}catch(error){commandError(error)}}
async function handleStartShift(){try{const latest=await kfePresentationApi.read.latestWorkOdometer();const odometer=Number(latest?.odometer);if(!Number.isFinite(odometer)||odometer<0)throw new Error('Authoritative start odometer is unavailable');await kfePresentationApi.commands.startShift({startOdometer:odometer});await refreshWorkState()}catch(error){commandError(error)}}
async function handleStartBusinessTrip(){try{const latest=await kfePresentationApi.read.latestWorkOdometer();const odometer=Number(latest?.odometer);if(!Number.isFinite(odometer)||odometer<0)throw new Error('Authoritative start odometer is unavailable');await kfePresentationApi.commands.startTrip({trip_type:'BUSINESS',start_odometer_km:odometer});await refreshWorkState()}catch(error){commandError(error)}}
async function handleStartPersonalTrip(){try{const latest=await kfePresentationApi.read.latestWorkOdometer();const odometer=Number(latest?.odometer);if(!Number.isFinite(odometer)||odometer<0)throw new Error('Authoritative start odometer is unavailable');await kfePresentationApi.commands.startTrip({trip_type:'PERSONAL',start_odometer_km:odometer});await refreshWorkState()}catch(error){commandError(error)}}
async function handleEndShift(){try{const [shift,latest]=await Promise.all([kfePresentationApi.read.getActiveShift(),kfePresentationApi.read.latestWorkOdometer()]);const endOdometer=Number(latest?.odometer);if(!shift?.id||!Number.isFinite(endOdometer)||endOdometer<0)throw new Error('Active shift or authoritative end odometer is unavailable');await kfePresentationApi.commands.endShift({id:shift.id,endOdometer});await refreshAll()}catch(error){commandError(error)}}
async function handleEndBusinessTrip(){try{const [draft,latest]=await Promise.all([kfePresentationApi.read.getActiveTripDraft(),kfePresentationApi.read.latestWorkOdometer()]);const endOdometer=Number(latest?.odometer);if(!draft?.trip_id||!Number.isFinite(endOdometer)||endOdometer<0)throw new Error('Active business trip or authoritative end odometer is unavailable');await kfePresentationApi.commands.endTrip({trip_type:'BUSINESS',trip_id:draft.trip_id,end_odometer_km:endOdometer});await refreshAll()}catch(error){commandError(error)}}
async function handleEndPersonalTrip(){try{const [draft,latest]=await Promise.all([kfePresentationApi.read.getActiveTripDraft(),kfePresentationApi.read.latestWorkOdometer()]);const endOdometer=Number(latest?.odometer);if(!draft?.trip_id||!Number.isFinite(endOdometer)||endOdometer<0)throw new Error('Active personal trip or authoritative end odometer is unavailable');await kfePresentationApi.commands.endTrip({trip_type:'PERSONAL',trip_id:draft.trip_id,end_odometer_km:endOdometer});await refreshAll()}catch(error){commandError(error)}}
async function handleEndDay(){try{await kfePresentationApi.commands.endDay();await refreshAll()}catch(error){commandError(error)}}
function handleOnline(){online.value=true}function handleOffline(){online.value=false}
onMounted(()=>{window.addEventListener('online',handleOnline);window.addEventListener('offline',handleOffline);void loadPerformance();void loadWorkState()})
onUnmounted(()=>{window.removeEventListener('online',handleOnline);window.removeEventListener('offline',handleOffline)})
</script>
<template><section class="kfe-workspace" :class="{'work-stage':activeModule==='Work'}" :aria-label="activeModule==='Work'?'Work':undefined" aria-live="polite" @touchstart="handleTouchStart" @touchend="handleTouchEnd"><div v-if="userError" class="operational-error" role="alert"><span>{{ userError }}</span><button type="button" class="operational-error-close" aria-label="Dismiss error" @click="clearError">×</button></div><div id="work-viewport" v-show="activeModule==='Work'" class="work-stack"><DayStartCard v-if="currentWorkState==='DAY_START'" :latest-odometer="latestWorkOdometer?.odometer??null" @start-day="handleStartDay"/><template v-else-if="currentWorkState==='SHIFT_WAITING'&&!dayEndSummary?.shiftId"><ShiftWaitingCard @start-shift="handleStartShift" @start-personal-trip="handleStartPersonalTrip"/><WorkOperationsCard :fsm-state="currentWorkState" :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='SHIFT_WAITING'"><DayEndCard :summary="dayEndSummary" :day-ended="false" @end-day="handleEndDay"/><WorkOperationsCard :fsm-state="currentWorkState" :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='DAY_ENDED'"><WorkSummaryCard :shift-summary="completedShiftSummary" :daily-report="dailyOperationalReport"/></template><template v-else-if="currentWorkState==='SHIFT'"><ShiftCard :shift-metrics="shiftMetrics" @end-shift="handleEndShift" @start-business-trip="handleStartBusinessTrip" @start-personal-trip="handleStartPersonalTrip"/><WorkOperationsCard :fsm-state="currentWorkState" :performance="performanceModel" :daily-report="dailyOperationalReport" :active-shift-id="shiftMetrics?.shiftId??null" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='PERSONAL_TRIP'"><PersonalTripCard :trip-metrics="personalTripMetrics" :start-time="personalTripMetrics?.startTimeEpochMs??null" :start-odometer="personalTripMetrics?.startOdometer??null" :current-authoritative-odometer="latestWorkOdometer?.odometer??null" @end-personal-trip="handleEndPersonalTrip"/><WorkOperationsCard :fsm-state="currentWorkState" :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='BUSINESS_TRIP'"><BusinessTripCard :trip-metrics="businessTripMetrics" :start-time="businessTripMetrics?.startTimeEpochMs??null" :start-odometer="businessTripMetrics?.startOdometer??null" :current-authoritative-odometer="latestWorkOdometer?.odometer??null" @end-business-trip="handleEndBusinessTrip"/><WorkOperationsCard :fsm-state="currentWorkState" :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template></div><div v-show="activeModule==='Performance'"><PerformanceModuleView :online="online" :performance="performanceModel"/></div><div v-show="activeModule==='Admin'"><AdminModuleView :application="kfePresentationApi" :online="online"/></div></section></template>
<style scoped>.work-stage{width:100%;height:100%;min-height:0;overflow:auto;padding:10px;box-sizing:border-box}.work-stack{display:grid;gap:10px;width:100%;min-height:100%}.operational-error{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:10px;padding:10px 12px;border:1px solid #b42318;border-radius:8px;background:#fef3f2;color:#7a271a;font-weight:600}.operational-error-close{flex:0 0 auto;border:0;background:transparent;color:inherit;font-size:22px;line-height:1;cursor:pointer;padding:0 4px}@media(max-width:480px){.work-stage{padding:8px}}</style>
